package com.crm.invoice.client;
import com.fasterxml.jackson.databind.JsonNode;import org.springframework.stereotype.Component;import org.springframework.cloud.client.discovery.DiscoveryClient;import org.springframework.web.client.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import com.crm.invoice.service.InvoiceWorkAccess;import java.util.*;import java.math.BigDecimal;
@Component public class InvoiceSourceClient {private final DiscoveryClient discovery;public InvoiceSourceClient(DiscoveryClient d){discovery=d;}public record Fee(String id,String customerId,String currency,String serviceName,String sourceTimeId,String hours,String rate,String amount){}public record FeePage(List<Fee> content,int number,int totalPages,long totalElements){}
 public Fee get(long id,String bearer){return fee(read("fees-service","/api/fees/billing-candidates/"+id,Map.of(),bearer),Long.toString(id));}
 public FeePage list(String customer,String currency,int page,String bearer){InvoiceWorkAccess.id(customer);if(currency==null||!currency.matches("[A-Z]{3}")||page<0)throw new IllegalArgumentException("Invalid filters");var root=read("fees-service","/api/fees/billing-candidates",Map.of("customerId",customer,"currency",currency,"page",page),bearer);if(root==null||!root.isObject()||!root.path("content").isArray()||!root.path("number").isIntegralNumber()||!root.path("number").canConvertToInt()||root.path("number").intValue()!=page||!root.path("totalPages").isIntegralNumber()||!root.path("totalPages").canConvertToInt()||root.path("totalPages").intValue()<0||!root.path("totalElements").isIntegralNumber()||!root.path("totalElements").canConvertToLong()||root.path("totalElements").longValue()<0||root.path("content").size()>20)throw invalid();List<Fee> fees=new ArrayList<>();for(var row:root.path("content")){var f=fee(row,null);if(!f.customerId().equals(customer)||!f.currency().equals(currency))throw invalid();fees.add(f);}return new FeePage(fees,page,root.path("totalPages").intValue(),root.path("totalElements").longValue());}
 public void customer(String id,String bearer){InvoiceWorkAccess.id(id);var row=read("customer-service","/api/customers/"+id,Map.of(),bearer);if(row==null||!row.isObject()||!row.path("id").isIntegralNumber()||!row.path("id").canConvertToLong()||!Long.toString(row.path("id").longValue()).equals(id)||!row.path("archived").isBoolean()||!row.path("contactType").isTextual())throw invalid();if(row.path("archived").booleanValue()||!row.path("contactType").textValue().equals("CUSTOMER"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Active customer required");}
 private Fee fee(JsonNode row,String expected){try{if(row==null||!row.isObject()||!row.path("immutable").isBoolean()||!row.path("immutable").booleanValue())throw invalid();for(String key:List.of("id","customerId","currency","serviceName","sourceTimeId","hours","rate","amount"))if(!row.path(key).isTextual())throw invalid();String id=row.path("id").textValue();InvoiceWorkAccess.id(id);InvoiceWorkAccess.id(row.path("customerId").textValue());InvoiceWorkAccess.id(row.path("sourceTimeId").textValue());if(expected!=null&&!expected.equals(id)||!row.path("currency").textValue().matches("[A-Z]{3}")||row.path("serviceName").textValue().isBlank()||row.path("serviceName").textValue().length()>255)throw invalid();for(String key:List.of("hours","rate","amount"))if(!row.path(key).textValue().matches("[0-9]+(\\.[0-9]{1,2})?"))throw invalid();var hours=new BigDecimal(row.path("hours").textValue());var rate=new BigDecimal(row.path("rate").textValue());var amount=new BigDecimal(row.path("amount").textValue());if(hours.signum()<=0||hours.compareTo(new BigDecimal("999999.99"))>0||rate.signum()<=0||rate.compareTo(new BigDecimal("9999999999.99"))>0||amount.signum()<=0||amount.compareTo(new BigDecimal("9999999999.99"))>0||hours.multiply(rate).setScale(2,java.math.RoundingMode.HALF_UP).compareTo(amount)!=0)throw invalid();return new Fee(id,row.path("customerId").textValue(),row.path("currency").textValue(),row.path("serviceName").textValue(),row.path("sourceTimeId").textValue(),hours.toPlainString(),rate.toPlainString(),amount.toPlainString());}catch(IllegalArgumentException e){throw invalid();}}
 public JsonNode read(String service,String path,Map<String,Object> params,String bearer){if(bearer==null||!bearer.startsWith("Bearer ")||bearer.substring(7).isBlank())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);var instances=discovery.getInstances(service);if(instances.isEmpty())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE);try{var f=new org.springframework.http.client.SimpleClientHttpRequestFactory(){@Override protected void prepareConnection(java.net.HttpURLConnection c,String method)throws java.io.IOException{super.prepareConnection(c,method);c.setInstanceFollowRedirects(false);}};f.setProxy(java.net.Proxy.NO_PROXY);f.setConnectTimeout(2000);f.setReadTimeout(2000);return RestClient.builder().baseUrl(instances.getFirst().getUri().toString()).requestFactory(f).build().get().uri(builder->{builder.path(path);params.forEach(builder::queryParam);return builder.build();}).header(HttpHeaders.AUTHORIZATION,bearer).retrieve().onStatus(s->s.is3xxRedirection(),(a,b)->{throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE);}).body(JsonNode.class);}catch(RestClientResponseException e){int code=e.getStatusCode().value();throw new ResponseStatusException(code==401?HttpStatus.UNAUTHORIZED:code==403?HttpStatus.FORBIDDEN:code==404?HttpStatus.NOT_FOUND:code==409?HttpStatus.CONFLICT:code>=500?HttpStatus.SERVICE_UNAVAILABLE:HttpStatus.BAD_GATEWAY,"Source service unavailable");}catch(ResourceAccessException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE);}catch(RestClientException e){throw invalid();}}
 private ResponseStatusException invalid(){return new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Invalid source contract");}
}
